import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { mockTransactions } from '../../mockData';  // Ensure the mockData file exists and has your mock transactions
import './Transactions.css';

function Transactions() {
  // State
  const [transactions, setTransactions] = useState(mockTransactions);
  const [filter, setFilter] = useState('all'); // all, sent, received
  const [searchTerm, setSearchTerm] = useState('');
  const [sortBy, setSortBy] = useState('date'); // date, amount
  const [sortOrder, setSortOrder] = useState('desc'); // asc, desc
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // Filter transactions based on type
  const filterTransactions = (type) => {
    setFilter(type);
  };

  // Search transactions
  const handleSearch = (event) => {
    setSearchTerm(event.target.value);
  };

  // Sort transactions
  const handleSort = (criteria) => {
    if (sortBy === criteria) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
    } else {
      setSortBy(criteria);
      setSortOrder('desc');
    }
  };

  // Filter and sort transactions
  const filteredAndSortedTransactions = transactions
    .filter(transaction => {
      if (filter === 'sent') return transaction.type === 'send';
      if (filter === 'received') return transaction.type === 'receive';
      return true;
    })
    .filter(transaction => {
      const searchLower = searchTerm.toLowerCase();
      return (
        transaction.id.toLowerCase().includes(searchLower) ||
        (transaction.recipient || '').toLowerCase().includes(searchLower) ||
        (transaction.sender || '').toLowerCase().includes(searchLower) ||
        transaction.description.toLowerCase().includes(searchLower)
      );
    })
    .sort((a, b) => {
      if (sortBy === 'date') {
        return sortOrder === 'asc' 
          ? new Date(a.date) - new Date(b.date)
          : new Date(b.date) - new Date(a.date);
      }
      if (sortBy === 'amount') {
        return sortOrder === 'asc' 
          ? a.amount - b.amount
          : b.amount - a.amount;
      }
      return 0;
    });

  // Load transactions (simulating API call)
  useEffect(() => {
    const loadTransactions = async () => {
      setLoading(true);
      try {
        await new Promise(resolve => setTimeout(resolve, 1000)); // Simulate delay
        setTransactions(mockTransactions);
        setError(null);
      } catch (err) {
        setError('Failed to load transactions');
      } finally {
        setLoading(false);
      }
    };

    loadTransactions();
  }, []);

  if (loading) {
    return <div className="loading-transactions">Loading transactions...</div>;
  }

  if (error) {
    return <div className="error-message">{error}</div>;
  }

  return (
    <div className="transactions-page">
      {/* Header */}
      <header className="transactions-header">
        <h2>Transaction History</h2>

        {/* Search Bar */}
        <div className="search-bar">
          <input
            type="text"
            placeholder="Search transactions..."
            value={searchTerm}
            onChange={handleSearch}
          />
        </div>
      </header>

      {/* Filters */}
      <div className="filters">
        <button className={filter === 'all' ? 'active' : ''} onClick={() => filterTransactions('all')}>
          All
        </button>
        <button className={filter === 'sent' ? 'active' : ''} onClick={() => filterTransactions('sent')}>
          Sent
        </button>
        <button className={filter === 'received' ? 'active' : ''} onClick={() => filterTransactions('received')}>
          Received
        </button>
      </div>

      {/* Sort Options */}
      <div className="sort-options">
        <button onClick={() => handleSort('date')}>
          Date {sortBy === 'date' && (sortOrder === 'asc' ? '↑' : '↓')}
        </button>
        <button onClick={() => handleSort('amount')}>
          Amount {sortBy === 'amount' && (sortOrder === 'asc' ? '↑' : '↓')}
        </button>
      </div>

      {/* Transactions List */}
      <div className="transactions-list">
        {filteredAndSortedTransactions.length === 0 ? (
          <div className="no-transactions">No transactions found</div>
        ) : (
          filteredAndSortedTransactions.map(transaction => (
            <Link to={`/transactions/${transaction.id}`} key={transaction.id} className="transaction-item">
              <div className="transaction-info">
                <p className="transaction-type">
                  {transaction.type === 'send' ? 'Sent to' : 'Received from'}
                </p>
                <p className="transaction-party">
                  {transaction.type === 'send' ? transaction.recipient : transaction.sender}
                </p>
                <p className="transaction-description">{transaction.description}</p>
                <p className="transaction-date">{transaction.date}</p>
              </div>
              <div className="transaction-amount">
                <p className={`amount ${transaction.type}`}>
                  {transaction.type === 'send' ? '-' : '+'}${transaction.amount}
                </p>
                <p className={`status ${transaction.status}`}>{transaction.status}</p>
              </div>
            </Link>
          ))
        )}
      </div>
    </div>
  );
}

export default Transactions;
